+    it('does not mutate the input exclude array', () => {
+      const input: {
+        length: number;
+        casing: 'mixed';
+        exclude: string[];
+      } = Object.freeze({
+        length: 5,
+        casing: 'mixed',
+        exclude: ['a', '%'],
+      });
