diff --git a/test/jar_serialization_test.js b/test/jar_serialization_test.js
new file mode 100644
index 0000000..8c0b388
--- /dev/null
+++ b/test/jar_serialization_test.js
@@ -0,0 +1,255 @@
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
+
